constexpr u32 RUN_COUNT = 175290;

// Unpacks RUNS into a flat WIDTH*HEIGHT pixel buffer suitable for
// Graphics::draw_image. Allocates PIXEL_COUNT * sizeof(u32) on the heap
// (about 1157 KB) — call this once and keep the returned pointer
// around (e.g. as a member/global), rather than decoding every frame.
// Returns nullptr if the allocation fails.
inline u32 *decode() {
  u32 *buffer = (u32 *)kmalloc(PIXEL_COUNT * sizeof(u32));

  if (!buffer)
    return nullptr;

  u32 pos = 0;

  for (u32 i = 0; i < RUN_COUNT; i++) {
    const Run &run = RUNS[i];

    for (u16 j = 0; j < run.count; j++)
      buffer[pos++] = run.color;
  }

  return buffer;
}

